-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.128.0',
  '2026-11-11',
  'Почта — журнал отбитых попыток; новая страница «Коннектор»',
  E'Почта. Рядом с «Защитой» появилась вкладка «Попытки» — сам журнал отказов, а не только их число: кто подключался, чем представлялся и, главное, НА КАКОЙ адрес пытался писать. Сверху сводка — куда стучались чаще всего и по каким причинам отбили; нажатие на строку сводки оставляет только её, рядом поиск по IP, адресу, отправителю и HELO. Цифра «Отбито попыток» на карточке теперь кликабельная и ведёт туда же.\n\nЖурнал намеренно неполный: 30 дней и не больше пяти тысяч строк, а мусорные команды одного бота сворачиваются в одну строку со счётчиком. Иначе лог порта 25, который перебирают круглосуточно, весил бы больше самой почты. Поэтому цифра на карточке (она считается с самого запуска почты) больше, чем строк в журнале, и вкладка об этом предупреждает.\n\nКоннектор — новая страница. Она связывает страницы между собой: «если пришло такое письмо — поставь отметку в таком трекере». Правило собирается из источника (пока это почта, событие — пришло письмо), условий и результатов. Условий может быть сколько угодно: поле письма (от кого, тема, текст, адрес получателя, есть ли вложения, спам ли), операция (содержит, равно, начинается, заканчивается, регулярка, пусто) и значение. Условия собираются в группы «и» и «или», а группы вкладываются друг в друга — так описывается что угодно вроде «от Яндекс Go ИЛИ в теме Яндекс Go, и при этом не спам». Регистр в сравнениях не важен.\n\nРезультатов тоже может быть несколько: отметка в трекере (цветом или эмодзи из его набора, у счётчиков — прибавка), сообщение в Telegram с подстановкой темы, отправителя, адреса и даты, или пометка письма — прочитано, звёздочка, в архив.\n\nОтметка ставится в день СОБЫТИЯ, а не в день срабатывания: отчёт о поездке, пришедший в час ночи, отметит вечер поездки — с учётом того, во сколько у трекера начинается день. Одно письмо правило отметит только один раз, сколько бы раз его ни прогоняли.\n\nПри настройке главная кнопка — «Проверить»: выбираете письмо из последних, и правило показывает по каждому условию, сошлось оно или нет и что лежало в поле, ничего при этом не делая. Когда правило готово, «Применить к письму» прогоняет его по-настоящему — это для писем, пришедших до того, как правило появилось. На вкладке «Журнал» видно, что и когда сработало.',
  E'Почта, журнал попыток. Миграция 0184: таблица mail_attempts (время, ip, ptr, helo, mail_from, rcpt, address_id, stage, reason, code, blocked, tls, hits) + индексы по времени и по IP. Отказ от построчного лога порта 25 остаётся в силе, поэтому журнал ограничен с трёх сторон: строка пишется только на осмысленном отказе (session.attempt() в точках, где уже проставляется s.reason), протокольный мусор одной сессии сворачивается в ОДНУ строку с hits в finish(), а уже заблокированный IP, продолжающий стучаться, не пишется вообще — только сам момент блокировки (smtpd.serve, ветка tooMany). Хранение режет store.PruneMailAttempts (30 дней / 5000 строк) из housekeeping приёмника, тикер 10 минут.\n\nПричина «неизвестный получатель» разделена: заведённый, но выключенный адрес пишется как «адрес выключен» вместе с address_id — это другая история, перебор это или человек сам выключил адрес и забыл. GET /mail/attempts отдаёт строки (фильтры ip/rcpt/reason/q, limit/offset) и сводку: since (с какого момента ведётся), total, за сутки, топ-15 адресов и причин с числом разных IP.\n\nКоннектор. Миграция 0185: connector_rules (sources/match/actions JSONB, tz_offset_minutes, runs, last_run_at) и connector_runs с УНИКАЛЬНЫМ частичным индексом (rule_id, source, event_id) WHERE event_id IS NOT NULL.\n\nДерево условий — JSONB, а не таблицы: вложенные И/ИЛИ в реляционной схеме пришлось бы собирать рекурсивным запросом на каждую проверку, а правило всегда читается и пишется целиком. Один тип store.ConnectorNode на оба вида узла, различие — непустой op: группа {"op":"and|or","nodes":[…]}, лист {"field","cmp","value"}. Границы (connector.maxDepth 5, maxNodes 50, maxActions 10, значение 500 символов) не от жадности: дерево приходит из браузера целиком и проверяется рекурсией. Пустая группа значит «условий нет» и подходит под любое событие — и для «и», и для «или»: логически пустое ИЛИ ложно, но правило, которое никогда не срабатывает, человеку объяснить нечем.\n\nРеестр источников, полей, операций и результатов живёт на бэкенде (connector/meta.go) и отдаётся в overview.meta — формы рисуются по нему, поэтому новое поле это запись в реестре, а не правка фронтенда. Новый источник = запись в Sources + сбор connector.Event (поля в Text/Flags) + вызов движка там, где событие случается; движок, дерево, журнал и страница от вида источника не зависят.\n\nИдемпотентность: ClaimConnectorRun занимает строку журнала ДО выполнения результатов, и уникальный индекс не даёт отметить одно письмо дважды (повторный разбор, перезапуск, кнопка «применить»). Ручное применение идёт с force — ON CONFLICT DO UPDATE, человек просит сам. store.SetMark ставит отметку через INSERT … ON CONFLICT DO NOTHING, а НЕ через ToggleMark: иначе второе событие за день снимало бы отметку, поставленную первым. День считается store.TrackerDay(ev.At, rule.tz_offset_minutes, cat.day_start_minutes) — день события и сдвинутые сутки трекера; пояс хранится на правиле, как у напоминаний.\n\nЖурнал пишет только сработавшие правила и ошибки (строка на каждое «не подошло» = журнал из мусора), у правила держатся последние 100 строк. На вопрос «почему не сработало» отвечает POST /connector/test: он не выполняет результаты, а возвращает connector.Trace — разбор, повторяющий форму дерева, с ✓/✗ и значением поля у каждого листа. Правило уходит в проверку ТЕЛОМ, а не по id: настраивать надо и несохранённое, иначе правило не собрать, не насорив в трекере.\n\nПриёмник почты зовёт коннектор через интерфейс smtpd.Connector (как и разбор чеков), таймаут на прогон 30 секунд: приёмник ждёт его в своей горутине, подвисшее правило задержало бы 250 OK. Ошибки правила событие не ломают — письмо уже сохранено, всё падает в журнал со статусом error. Трекеры, адреса и последние письма страница берёт из /connector/overview, а не из API других страниц: у «Коннектора» свой доступ. Вид уведомлений бота — connector.\n\nПроверено локально на одноразовой базе с настоящим SMTP-приёмником: 52 проверки. Письмо от no-reply@taxi.yandex.ru само поставило отметку нужным цветом в день письма, пересланное письмо прошло по ветке «или» по теме, спам отсекся, выключенное правило молчало, повторное применение не удвоило отметку («уже была отмечена») и не раздуло журнал, счётчик прибавил +2 и ещё +2, подстановки в сообщении развернулись, две пометки письма применились (архив + прочитано), negative-правило вернуло matched=false, неизвестное поле и цвет вида «red; background:url(x)» отвергнуты с объяснением, дубль строки журнала отбит уникальным индексом. По почте: перебор двух адресов дал две строки с их адресами, попытка ретрансляции — свою, четыре мусорные команды свернулись в одну строку с hits=3, фильтры по адресу, причине и HELO работают, принятое письмо в журнал не попало.'
);
-- +goose StatementEnd

